def run(args, cwd=None, timeout=120):
    """Run a command, returning (returncode, stdout, stderr) with output stripped."""
    try:
        proc = subprocess.run(
            args, cwd=cwd, capture_output=True, text=True, timeout=timeout,
            env={**os.environ, "GIT_OPTIONAL_LOCKS": "0"}
        )

